definitions.erp.create_attendance_hpp_pool_v1(jsonb,:
CREATE OR REPLACE FUNCTION erp.create_attendance_hpp_pool_v1(p_payload jsonb, p_client_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_operation constant text := 'create_attendance_hpp_pool_v1';
  v_hash text;
  v_cached jsonb;
  v_period_start date;
  v_period_end date;
  v_reason text;
  v_correction_of uuid;
  v_preview jsonb;
  v_manifest jsonb;
  v_pool erp.attendance_hpp_pools%rowtype;
  v_response jsonb;
begin
  perform erp.require_owner_admin();
  perform erp._cp3_assert_closed_json_object(
    p_payload,
    array['period_start','period_end','reason'],
    array['period_start','period_end','reason','correction_of_pool_id'],
    'attendance HPP pool payload'
  );
  if jsonb_typeof(p_payload->'period_start') is distinct from 'string'
     or jsonb_typeof(p_payload->'period_end') is distinct from 'string'
     or jsonb_typeof(p_payload->'reason') is distinct from 'string'
     or (p_payload ? 'correction_of_pool_id'
         and coalesce(jsonb_typeof(p_payload->'correction_of_pool_id'), 'missing') not in ('string','null')) then
    raise exception 'Attendance HPP pool payload has invalid field types';
  end if;

  v_period_start := erp._cp3_parse_canonical_date(p_payload->>'period_start', 'attendance HPP period_start');
  v_period_end := erp._cp3_parse_canonical_date(p_payload->>'period_end', 'attendance HPP period_end');
  v_reason := nullif(btrim(p_payload->>'reason'), '');
  v_correction_of := nullif(p_payload->>'correction_of_pool_id', '')::uuid;
  if v_reason is null then raise exception 'Attendance HPP pool reason is required'; end if;

  v_hash := erp._request_hash(jsonb_build_object('payload', p_payload));
  v_cached := erp._idempotency_begin(v_operation, p_client_request_id, v_hash);
  if v_cached is not null then return v_cached; end if;

  perform erp._cp3_lock_business_period(v_period_start, v_period_end);
  perform erp._cp3_lock_manifest_contractors(v_period_start, v_period_end);

  if exists (
    select 1 from erp.attendance_hpp_pools p
    where p.period_start = v_period_start
      and p.period_end = v_period_end
      and p.status in ('DRAFT','ACTIVE')
  ) then
    raise exception 'A DRAFT/ACTIVE attendance HPP pool already exists for this exact period';
  end if;
  if v_correction_of is not null and not exists (
    select 1 from erp.attendance_hpp_pools p
    where p.id = v_correction_of
      and p.status = 'CANCELLED'
      and p.period_start = v_period_start
      and p.period_end = v_period_end
  ) then
    raise exception 'correction_of_pool_id must reference a CANCELLED pool for the same exact period';
  end if;

  v_preview := erp.preview_attendance_hpp_pool_v1(v_period_start, v_period_end);
  v_manifest := v_preview->'manifest';

  insert into erp.attendance_hpp_pools(
    pool_number, period_start, period_end, correction_of_pool_id,
    numerator_amount, denominator_qty, unit_cost_per_sewn_pcs,
    source_manifest, source_manifest_sha256,
    reason, created_by
  ) values (
    'AHPP-' || to_char(clock_timestamp() at time zone 'UTC', 'YYYYMMDDHH24MISSUS') || '-' || substr(gen_random_uuid()::text, 1, 8),
    v_period_start, v_period_end, v_correction_of,
    (v_preview->>'numerator_amount')::numeric,
    (v_preview->>'denominator_qty')::bigint,
    (v_preview->>'unit_cost_per_sewn_pcs')::numeric,
    v_manifest, v_preview->>'manifest_sha256',
    v_reason, erp.current_app_user_id()
  ) returning * into v_pool;

  insert into erp.attendance_hpp_pool_sources(
    pool_id, payroll_id, contractor_id, policy_version_id,
    original_debit_journal_line_id,
    contractor_role_snapshot, attendance_required_snapshot, is_special_snapshot,
    attendance_amount
  )
  select
    v_pool.id,
    (x->>'payroll_id')::uuid,
    (x->>'contractor_id')::uuid,
    (x->>'policy_version_id')::uuid,
    (x->>'original_debit_journal_line_id')::uuid,
    x->>'contractor_role_snapshot',
    (x->>'attendance_required_snapshot')::boolean,
    (x->>'is_special_snapshot')::boolean,
    ((x->>'attendance_amount_cents')::bigint / 100.0)::numeric(20,2)
  from jsonb_array_elements(v_manifest->'sources') x;

  with destination as (
    select
      (x->>'sewing_terminal_event_id')::uuid sewing_terminal_event_id,
      (x->>'contractor_id')::uuid contractor_id,
      (x->>'po_id')::uuid po_id,
      nullif(x->>'cutting_group_id', '')::uuid cutting_group_id,
      (x->>'sewing_qty')::integer sewing_qty,
      sum((x->>'sewing_qty')::bigint) over (
        order by (x->>'physical_at_epoch_us')::bigint,
                 (x->>'sewing_terminal_event_id')::uuid
        rows between unbounded preceding and current row
      ) cumulative_qty,
      coalesce(sum((x->>'sewing_qty')::bigint) over (
        order by (x->>'physical_at_epoch_us')::bigint,
                 (x->>'sewing_terminal_event_id')::uuid
        rows between unbounded preceding and 1 preceding
      ), 0) previous_cumulative_qty
    from jsonb_array_elements(v_manifest->'destinations') x
  ), source as (
    select s.*, round(s.attendance_amount * 100)::bigint source_cents
    from erp.attendance_hpp_pool_sources s
    where s.pool_id = v_pool.id
  )
  insert into erp.attendance_hpp_pool_allocations(
    pool_id, pool_source_id, sewing_terminal_event_id,
    contractor_id, po_id, cutting_group_id,
    sewing_qty, allocated_amount
  )
  select
    v_pool.id, s.id, d.sewing_terminal_event_id,
    d.contractor_id, d.po_id, d.cutting_group_id,
    d.sewing_qty,
    (
      floor(s.source_cents::numeric * d.cumulative_qty::numeric / v_pool.denominator_qty)
      - floor(s.source_cents::numeric * d.previous_cumulative_qty::numeric / v_pool.denominator_qty)
    ) / 100.0
  from source s cross join destination d
  order by s.id, d.cumulative_qty, d.sewing_terminal_event_id;

  if exists (
    select 1
    from erp.attendance_hpp_pool_sources s
    left join erp.attendance_hpp_pool_allocations a on a.pool_source_id = s.id
    where s.pool_id = v_pool.id
    group by s.id, s.attendance_amount
    having round(coalesce(sum(a.allocated_amount), 0), 2) is distinct from round(s.attendance_amount, 2)
  ) then
    raise exception 'Deterministic allocation failed to reconcile a source debit line exactly to cents';
  end if;

  insert into erp.audit_logs(entity_type, entity_id, action, new_data, changed_by, change_reason)
  values (
    'attendance_hpp_pools', v_pool.id, 'INSERT',
    jsonb_build_object(
      'period_start', v_pool.period_start,
      'period_end', v_pool.period_end,
      'numerator_amount', v_pool.numerator_amount,
      'denominator_qty', v_pool.denominator_qty,
      'manifest_sha256', v_pool.source_manifest_sha256,
      'correction_of_pool_id', v_pool.correction_of_pool_id,
      'lifecycle_action', 'CREATE_DRAFT'
    ),
    erp.current_app_user_id(), v_reason
  );

  v_response := jsonb_build_object(
    'pool_id', v_pool.id,
    'pool_number', v_pool.pool_number,
    'status', v_pool.status,
    'row_version', v_pool.row_version,
    'numerator_amount', v_pool.numerator_amount,
    'denominator_qty', v_pool.denominator_qty,
    'unit_cost_per_sewn_pcs', v_pool.unit_cost_per_sewn_pcs,
    'manifest_sha256', v_pool.source_manifest_sha256
  );
  return erp._idempotency_complete(v_operation, p_client_request_id, v_response);
end;
$function$

definitions.erp.activate_attendance_hpp_pool_v1(uuid:
CREATE OR REPLACE FUNCTION erp.activate_attendance_hpp_pool_v1(p_pool_id uuid, p_reason text, p_client_request_id uuid, p_expected_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_operation constant text := 'activate_attendance_hpp_pool_v1';
  v_hash text;
  v_cached jsonb;
  v_pool erp.attendance_hpp_pools%rowtype;
  v_lines jsonb := '[]'::jsonb;
  v_journal_id uuid;
  v_effective_date date;
  v_line record;
  v_response jsonb;
begin
  perform erp.require_owner_admin();
  if p_pool_id is null or p_expected_version is null then
    raise exception 'pool_id and expected_version are required';
  end if;
  if coalesce(btrim(p_reason), '') = '' then
    raise exception 'Attendance HPP activation reason is required';
  end if;

  v_hash := erp._request_hash(jsonb_build_object(
    'pool_id', p_pool_id,
    'reason', btrim(p_reason),
    'expected_version', p_expected_version
  ));
  v_cached := erp._idempotency_begin(v_operation, p_client_request_id, v_hash);
  if v_cached is not null then return v_cached; end if;

  select * into v_pool
  from erp.attendance_hpp_pools
  where id = p_pool_id
  for update;

  if v_pool.id is null then raise exception 'Attendance HPP pool not found'; end if;
  if v_pool.status <> 'DRAFT' then raise exception 'Only DRAFT attendance HPP pool can be activated'; end if;
  if v_pool.row_version <> p_expected_version then
    raise exception 'STALE_VERSION expected %, current %', p_expected_version, v_pool.row_version;
  end if;
  if v_pool.numerator_amount <= 0 or v_pool.denominator_qty <= 0 then
    raise exception 'Attendance HPP activation requires positive numerator and immutable SELESAI_DIJAHIT denominator';
  end if;

  perform erp._cp3_lock_business_period(v_pool.period_start, v_pool.period_end);
  perform erp._cp3_lock_manifest_contractors(v_pool.period_start, v_pool.period_end);

  if exists (
    select 1 from erp.attendance_hpp_pools p
    where p.id <> v_pool.id
      and p.period_start = v_pool.period_start
      and p.period_end = v_pool.period_end
      and p.status = 'ACTIVE'
  ) then
    raise exception 'Another ACTIVE attendance HPP pool already owns this exact period';
  end if;

  perform erp.validate_attendance_hpp_pool_v1(v_pool.id);

  select coalesce(jsonb_agg(jsonb_build_object(
    'mapping_key', 'WIP',
    'debit', amount,
    'credit', 0,
    'contractor_id', contractor_id,
    'po_id', po_id,
    'description', 'Attendance HPP destination PO ' || po_id::text
  ) order by po_id, contractor_id), '[]'::jsonb)
  into v_lines
  from (
    select po_id, contractor_id, round(sum(allocated_amount),2) amount
    from erp.attendance_hpp_pool_allocations
    where pool_id = v_pool.id
    group by po_id, contractor_id
    having round(sum(allocated_amount),2) > 0
  ) d;

  v_lines := v_lines || coalesce((
    select jsonb_agg(jsonb_build_object(
      'account_id', jl.account_id,
      'debit', 0,
      'credit', round(s.attendance_amount,2),
      'contractor_id', s.contractor_id,
      'description', 'Attendance HPP source debit line ' || s.original_debit_journal_line_id::text
    ) order by s.original_debit_journal_line_id)
    from erp.attendance_hpp_pool_sources s
    join erp.journal_lines jl on jl.id = s.original_debit_journal_line_id
    where s.pool_id = v_pool.id
  ), '[]'::jsonb);

  v_journal_id := erp.post_journal(
    'ATTENDANCE_HPP_POOL', v_pool.id, v_pool.period_end,
    'Allocate normal-Mandor attendance cost by immutable SELESAI_DIJAHIT',
    v_lines
  );
  select transaction_date into v_effective_date
  from erp.journal_entries where id=v_journal_id;

  for v_line in
    select jl.id, jl.po_id, jl.debit
    from erp.journal_lines jl
    where jl.journal_entry_id = v_journal_id
      and jl.debit > 0
      and jl.po_id is not null
  loop
    insert into erp.attendance_hpp_journal_line_links(
      pool_id, journal_line_id, link_type, po_id, amount
    ) values (
      v_pool.id, v_line.id, 'DESTINATION_DEBIT', v_line.po_id, v_line.debit
    );
  end loop;

  for v_line in
    select s.id as pool_source_id, s.original_debit_journal_line_id,
           s.attendance_amount, jl2.id as journal_line_id
    from erp.attendance_hpp_pool_sources s
    join erp.journal_lines jl2
      on jl2.journal_entry_id = v_journal_id
     and jl2.credit = round(s.attendance_amount,2)
     and jl2.description = 'Attendance HPP source debit line ' || s.original_debit_journal_line_id::text
    where s.pool_id = v_pool.id
    order by s.original_debit_journal_line_id
  loop
    insert into erp.attendance_hpp_journal_line_links(
      pool_id, journal_line_id, link_type,
      pool_source_id, original_debit_journal_line_id, amount
    ) values (
      v_pool.id, v_line.journal_line_id, 'SOURCE_CREDIT',
      v_line.pool_source_id, v_line.original_debit_journal_line_id,
      v_line.attendance_amount
    );
  end loop;

  update erp.attendance_hpp_pools
  set status = 'ACTIVE',
      post_journal_entry_id = v_journal_id,
      activated_by = erp.current_app_user_id(),
      activated_at = clock_timestamp(),
      row_version = row_version + 1
  where id = v_pool.id
  returning * into v_pool;

  perform erp.validate_attendance_hpp_pool_v1(v_pool.id);

  for v_line in
    select distinct a.po_id
    from erp.attendance_hpp_pool_allocations a
    where a.pool_id=v_pool.id
    order by a.po_id
  loop
    perform erp.rebuild_po_hpp(v_line.po_id,'Attendance HPP pool activation '||v_pool.id::text);
    perform erp.propagate_conversion_hpp_for_po(v_line.po_id);
    perform erp.sync_po_hpp_to_gl(v_line.po_id,v_effective_date);
    if exists(select 1 from erp.production_orders where id=v_line.po_id and status='FINISHED') then
      perform erp.sync_finished_po_wip_residual(v_line.po_id,v_effective_date,'Attendance HPP pool activation '||v_pool.id::text);
    end if;
  end loop;

  insert into erp.audit_logs(entity_type, entity_id, action, new_data, changed_by, change_reason)
  values (
    'attendance_hpp_pools', v_pool.id, 'POST',
    jsonb_build_object(
      'journal_entry_id', v_journal_id,
      'numerator_amount', v_pool.numerator_amount,
      'denominator_qty', v_pool.denominator_qty,
      'manifest_sha256', v_pool.source_manifest_sha256,
      'lifecycle_action', 'ACTIVATE'
    ),
    erp.current_app_user_id(), btrim(p_reason)
  );

  v_response := jsonb_build_object(
    'pool_id', v_pool.id,
    'status', v_pool.status,
    'row_version', v_pool.row_version,
    'journal_entry_id', v_pool.post_journal_entry_id,
    'validation', 'PASS'
  );
  return erp._idempotency_complete(v_operation, p_client_request_id, v_response);
end;
$function$

definitions.erp.cancel_attendance_hpp_pool_v1(uuid,t:
CREATE OR REPLACE FUNCTION erp.cancel_attendance_hpp_pool_v1(p_pool_id uuid, p_reason text, p_client_request_id uuid, p_expected_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_operation constant text := 'cancel_attendance_hpp_pool_v1';
  v_hash text;
  v_cached jsonb;
  v_pool erp.attendance_hpp_pools%rowtype;
  v_reversal_journal_id uuid;
  v_effective_date date;
  v_po_id uuid;
  v_response jsonb;
begin
  perform erp.require_owner_admin();
  if p_pool_id is null or p_expected_version is null then
    raise exception 'pool_id and expected_version are required';
  end if;
  if coalesce(btrim(p_reason), '') = '' then
    raise exception 'Attendance HPP cancellation reason is required';
  end if;

  v_hash := erp._request_hash(jsonb_build_object(
    'pool_id', p_pool_id,
    'reason', btrim(p_reason),
    'expected_version', p_expected_version
  ));
  v_cached := erp._idempotency_begin(v_operation, p_client_request_id, v_hash);
  if v_cached is not null then return v_cached; end if;

  select * into v_pool
  from erp.attendance_hpp_pools
  where id = p_pool_id
  for update;

  if v_pool.id is null then raise exception 'Attendance HPP pool not found'; end if;
  if v_pool.status not in ('DRAFT','ACTIVE') then
    raise exception 'Only DRAFT or ACTIVE attendance HPP pool can be cancelled';
  end if;
  if v_pool.row_version <> p_expected_version then
    raise exception 'STALE_VERSION expected %, current %', p_expected_version, v_pool.row_version;
  end if;

  perform erp._cp3_lock_business_period(v_pool.period_start, v_pool.period_end);

  if v_pool.status = 'DRAFT' then
    update erp.attendance_hpp_pools
    set status = 'VOIDED',
        cancellation_reason = btrim(p_reason),
        cancelled_by = erp.current_app_user_id(),
        cancelled_at = clock_timestamp(),
        row_version = row_version + 1
    where id = v_pool.id
    returning * into v_pool;

    insert into erp.audit_logs(entity_type, entity_id, action, new_data, changed_by, change_reason)
    values (
      'attendance_hpp_pools', v_pool.id, 'UPDATE',
      jsonb_build_object('previous_status','DRAFT','new_status','VOIDED','lifecycle_action','VOID_DRAFT'),
      erp.current_app_user_id(), btrim(p_reason)
    );

    v_response := jsonb_build_object(
      'pool_id', v_pool.id,
      'status', v_pool.status,
      'row_version', v_pool.row_version,
      'reversal_journal_entry_id', null,
      'residue_expected', 0
    );
    return erp._idempotency_complete(v_operation, p_client_request_id, v_response);
  end if;

  if v_pool.post_journal_entry_id is null then
    raise exception 'ACTIVE attendance HPP pool has no source journal; cancellation stopped to avoid residue';
  end if;

  if not exists (
    select 1 from erp.journal_entries je
    where je.id = v_pool.post_journal_entry_id
      and je.status = 'POSTED'
      and je.source_type = 'ATTENDANCE_HPP_POOL'
      and je.source_id = v_pool.id
  ) then
    raise exception 'Pool journal is not an active posted ATTENDANCE_HPP_POOL journal';
  end if;

  v_reversal_journal_id := erp._cp3_r4_reverse_journal_internal(v_pool.post_journal_entry_id, btrim(p_reason));
  select transaction_date into v_effective_date
  from erp.journal_entries where id=v_reversal_journal_id;

  update erp.attendance_hpp_pools
  set status = 'CANCELLED',
      cancellation_journal_entry_id = v_reversal_journal_id,
      cancellation_reason = btrim(p_reason),
      cancelled_by = erp.current_app_user_id(),
      cancelled_at = clock_timestamp(),
      row_version = row_version + 1
  where id = v_pool.id
  returning * into v_pool;

  for v_po_id in
    select distinct a.po_id
    from erp.attendance_hpp_pool_allocations a
    where a.pool_id=v_pool.id
    order by a.po_id
  loop
    perform erp.rebuild_po_hpp(v_po_id,'Attendance HPP pool cancellation '||v_pool.id::text);
    perform erp.propagate_conversion_hpp_for_po(v_po_id);
    perform erp.sync_po_hpp_to_gl(v_po_id,v_effective_date);
    if exists(select 1 from erp.production_orders where id=v_po_id and status='FINISHED') then
      perform erp.sync_finished_po_wip_residual(v_po_id,v_effective_date,'Attendance HPP pool cancellation '||v_pool.id::text);
    end if;
  end loop;

  insert into erp.audit_logs(entity_type, entity_id, action, new_data, changed_by, change_reason)
  values (
    'attendance_hpp_pools', v_pool.id, 'REVERSE',
    jsonb_build_object(
      'post_journal_entry_id', v_pool.post_journal_entry_id,
      'cancellation_journal_entry_id', v_pool.cancellation_journal_entry_id,
      'previous_status', 'ACTIVE',
      'new_status', 'CANCELLED',
      'lifecycle_action', 'CANCEL_ACTIVE'
    ),
    erp.current_app_user_id(), btrim(p_reason)
  );

  v_response := jsonb_build_object(
    'pool_id', v_pool.id,
    'status', v_pool.status,
    'row_version', v_pool.row_version,
    'reversal_journal_entry_id', v_pool.cancellation_journal_entry_id,
    'residue_expected', 0
  );
  return erp._idempotency_complete(v_operation, p_client_request_id, v_response);
end;
$function$

definitions.erp.approve_payroll(uuid):
CREATE OR REPLACE FUNCTION erp.approve_payroll(p_payroll_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  p erp.payroll_settlements%rowtype;
  v_manual_reimburse numeric(20,2) := 0;
  v_extra_accrual numeric(20,2) := 0;
  v_negative_manual numeric(20,2) := 0;
  v_attendance numeric(20,2) := 0;
begin
  perform erp.require_owner_admin();
  perform erp.recalculate_payroll(p_payroll_id);
  select * into p from erp.payroll_settlements where id=p_payroll_id for update;
  if p.id is null or p.status not in ('CALCULATED','REVIEW') then
    raise exception 'Payroll must be CALCULATED/REVIEW before approval, current status %',p.status;
  end if;

  perform erp.check_opening_cash_advance_payroll_v1(p.id);
  perform erp.bb_check_opening_payable_payroll_v1(p.id);
  perform erp._cp3_lock_business_period(p.period_start,p.period_end);
  if exists(
    select 1 from erp.attendance_hpp_pools hp
    where hp.status='ACTIVE'
      and hp.period_start=p.period_start
      and hp.period_end=p.period_end
  ) then
    raise exception 'Attendance HPP pool for payroll period % through % is already ACTIVE. Cancel the ACTIVE pool first before approving this payroll.',p.period_start,p.period_end;
  end if;
  if exists (
    select 1 from erp.journal_entries je
    where je.source_id=p.id
      and je.source_type in ('PAYROLL_ATTENDANCE_ACCRUAL','PAYROLL_EXTRA_ACCRUAL','PAYROLL_MANUAL_REDUCTION')
      and je.status='POSTED'
  ) then
    raise exception 'Payroll approval accrual already exists; inspect duplicate/ambiguous approval state';
  end if;

  select coalesce(sum(amount),0) into v_manual_reimburse
  from erp.payroll_reimbursements
  -- BB (ALL-Y01): an imported contractor payable was recognized at cutover; paying it through payroll accrues nothing again.
  -- BC: a carried note return credit was recognized as CONTRACTOR_PAYABLE at the credit.
  where payroll_id=p.id and source_type not in('ACCESSORY_BOM','OPENING_PAYABLE','BC_RETURN_CARRY');
  v_attendance:=round(coalesce(p.attendance_total,0),2);
  v_extra_accrual:=round(v_manual_reimburse+greatest(p.manual_adjustment,0),2);
  v_negative_manual:=round(greatest(-p.manual_adjustment,0),2);

  update erp.payroll_settlements set status='APPROVED',updated_at=statement_timestamp() where id=p.id;

  if v_attendance>0 then
    perform erp.post_journal(
      'PAYROLL_ATTENDANCE_ACCRUAL',p.id,p.period_end,
      'Attendance payroll approved into unassigned WIP',
      jsonb_build_array(
        jsonb_build_object('mapping_key','WIP','debit',v_attendance,'credit',0,'contractor_id',p.contractor_id,
                           'description','Approved attendance cost awaiting SELESAI_DIJAHIT allocation'),
        jsonb_build_object('mapping_key','CONTRACTOR_PAYABLE','debit',0,'credit',v_attendance,'contractor_id',p.contractor_id,
                           'description','Approved attendance payable')
      )
    );
  end if;
  if v_extra_accrual>0 then
    perform erp.post_journal(
      'PAYROLL_EXTRA_ACCRUAL',p.id,p.period_end,
      'Approved manual reimbursement/manual payroll accrual',
      jsonb_build_array(
        jsonb_build_object('mapping_key','LABOR_COST','debit',v_extra_accrual,'credit',0,'contractor_id',p.contractor_id),
        jsonb_build_object('mapping_key','CONTRACTOR_PAYABLE','debit',0,'credit',v_extra_accrual,'contractor_id',p.contractor_id)
      )
    );
  end if;
  if v_negative_manual>0 then
    perform erp.post_journal(
      'PAYROLL_MANUAL_REDUCTION',p.id,p.period_end,
      'Approved negative manual payroll adjustment',
      jsonb_build_array(
        jsonb_build_object('mapping_key','CONTRACTOR_PAYABLE','debit',v_negative_manual,'credit',0,'contractor_id',p.contractor_id),
        jsonb_build_object('mapping_key','LABOR_COST','debit',0,'credit',v_negative_manual,'contractor_id',p.contractor_id)
      )
    );
  end if;

  insert into erp.audit_logs(entity_type,entity_id,action,new_data,changed_by,change_reason)
  values(
    'payroll_settlements',p.id,'POST',
    jsonb_build_object('lifecycle_action','APPROVE','attendance_accrual',v_attendance,
                       'extra_accrual',v_extra_accrual,'manual_reduction',v_negative_manual),
    erp.current_app_user_id(),'Payroll approved; cost recognition completed before payment'
  );
end;
$function$

definitions.erp.cancel_unpaid_payroll(uuid,text):
CREATE OR REPLACE FUNCTION erp.cancel_unpaid_payroll(p_payroll_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  p erp.payroll_settlements%rowtype;
  r record;
begin
  perform erp.require_owner_admin();
  if nullif(trim(p_reason),'') is null then raise exception 'Cancellation reason is required'; end if;
  select * into p from erp.payroll_settlements where id=p_payroll_id for update;
  if p.id is null then raise exception 'Payroll not found'; end if;
  if p.status='PAID' then raise exception 'Paid payroll requires a dedicated financial reversal, not unpaid cancellation'; end if;
  if p.status='REVERSED' then return; end if;
  if p.status not in ('DRAFT','CALCULATED','REVIEW','APPROVED') then raise exception 'Payroll cannot be cancelled in status %',p.status; end if;
  perform erp._cp3_lock_business_period(p.period_start,p.period_end);

  if exists(
    select 1 from erp.attendance_hpp_pool_sources s
    join erp.attendance_hpp_pools hp on hp.id=s.pool_id
    where s.payroll_id=p.id and hp.status='ACTIVE'
  ) then
    raise exception 'PAYROLL_CONSUMED_BY_ACTIVE_HPP_POOL: cancel the active attendance HPP pool first';
  end if;

  for r in
    select je.id from erp.journal_entries je
    where je.source_id=p.id
      and je.source_type in ('PAYROLL_ATTENDANCE_ACCRUAL','PAYROLL_EXTRA_ACCRUAL','PAYROLL_MANUAL_REDUCTION')
      and je.status='POSTED'
    order by je.posting_at desc,je.id desc
  loop perform erp._cp3_r4_reverse_journal_internal(r.id,p_reason); end loop;

  update erp.payroll_settlements set status='REVERSED',settled_at=null,updated_at=statement_timestamp() where id=p.id;
  for r in select distinct pd.contractor_issue_item_id id from erp.payroll_deductions pd
           where pd.payroll_id=p.id and pd.contractor_issue_item_id is not null
  loop perform erp.refresh_contractor_issue_payroll_status(r.id); end loop;
  for r in select distinct pr.source_id id from erp.payroll_reimbursements pr
           where pr.payroll_id=p.id and pr.source_type='ACCESSORY_BOM' and pr.source_id is not null
  loop
    update erp.contractor_accessory_reimbursement_entitlements e
    set payroll_status=case
      when exists(select 1 from erp.payroll_reimbursements pr2 join erp.payroll_settlements ps2 on ps2.id=pr2.payroll_id
                  where pr2.source_type='ACCESSORY_BOM' and pr2.source_id=e.id and ps2.status='PAID') then 'SETTLED'
      when exists(select 1 from erp.payroll_reimbursements pr2 join erp.payroll_settlements ps2 on ps2.id=pr2.payroll_id
                  where pr2.source_type='ACCESSORY_BOM' and pr2.source_id=e.id and ps2.status<>'REVERSED') then 'ALLOCATED'
      else 'UNALLOCATED' end
    where e.id=r.id;
  end loop;
  insert into erp.audit_logs(entity_type,entity_id,action,new_data,changed_by,change_reason)
  values('payroll_settlements',p.id,'CANCEL_UNPAID',jsonb_build_object('previous_status',p.status),erp.current_app_user_id(),p_reason);
end;
$function$

definitions.erp.reverse_paid_payroll(uuid,text):
CREATE OR REPLACE FUNCTION erp.reverse_paid_payroll(p_payroll_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  p erp.payroll_settlements%rowtype;
  r record;
begin
  perform erp.require_owner_admin();
  if nullif(trim(p_reason),'') is null then raise exception 'Payroll reversal reason is required'; end if;
  select * into p from erp.payroll_settlements where id=p_payroll_id for update;
  if p.id is null then raise exception 'Payroll not found'; end if;
  if p.status='REVERSED' then return; end if;
  if p.status<>'PAID' then raise exception 'Only PAID payroll uses reverse_paid_payroll; unpaid payroll uses cancel_unpaid_payroll'; end if;
  perform 1 from erp.opening_subledger_balances b where exists(select 1 from erp.payroll_deductions d
    where d.payroll_id=p.id and d.opening_cash_advance_balance_id=b.id) or exists(select 1 from erp.payroll_reimbursements pr
    where pr.payroll_id=p.id and pr.opening_payable_balance_id=b.id) order by b.id for update;
  perform erp._cp3_lock_business_period(p.period_start,p.period_end);
  if exists(
    select 1 from erp.attendance_hpp_pool_sources s
    join erp.attendance_hpp_pools hp on hp.id=s.pool_id
    where s.payroll_id=p.id and hp.status='ACTIVE'
  ) then
    raise exception 'PAYROLL_CONSUMED_BY_ACTIVE_HPP_POOL: cancel the active attendance HPP pool first';
  end if;

  for r in
    select je.id from erp.journal_entries je
    where je.source_id=p.id
      and je.source_type in ('PAYROLL_ATTENDANCE_ACCRUAL','PAYROLL_EXTRA_ACCRUAL','PAYROLL_MANUAL_REDUCTION',
                             'PAYROLL_MATERIAL_DEDUCTION','PAYROLL_OTHER_DEDUCTION','PAYROLL_PAYMENT','PAYROLL_CASH_ADVANCE_DEDUCTION')
      and je.status='POSTED'
    order by je.posting_at desc,je.id desc
  loop perform erp._cp3_r4_reverse_journal_internal(r.id,p_reason); end loop;

  update erp.payroll_settlements set status='REVERSED',settled_at=null,updated_at=statement_timestamp() where id=p.id;
  update erp.opening_subledger_balances b set settled_amount=b.settled_amount-x.amount,
    status=case when b.settled_amount-x.amount=b.original_amount then 'SETTLED' when b.settled_amount-x.amount>0 then 'PARTIAL' else 'OPEN' end,
    updated_at=statement_timestamp()
  from(select opening_cash_advance_balance_id id,sum(amount) amount from erp.payroll_deductions
    where payroll_id=p.id and deduction_type='CASH_ADVANCE' group by opening_cash_advance_balance_id) x where b.id=x.id;
  -- BB (ALL-Y01): the imported contractor payables this payroll paid are open again.
  update erp.opening_subledger_balances b set settled_amount=b.settled_amount-x.amount,
    status=case when b.settled_amount-x.amount=b.original_amount then 'SETTLED' when b.settled_amount-x.amount>0 then 'PARTIAL' else 'OPEN' end,
    updated_at=statement_timestamp()
  from(select opening_payable_balance_id id,sum(amount) amount from erp.payroll_reimbursements
    where payroll_id=p.id and source_type='OPENING_PAYABLE' group by opening_payable_balance_id) x where b.id=x.id;

  for r in select distinct pd.contractor_issue_item_id id from erp.payroll_deductions pd
           where pd.payroll_id=p.id and pd.contractor_issue_item_id is not null
  loop perform erp.refresh_contractor_issue_payroll_status(r.id); end loop;
  for r in select distinct pr.source_id id from erp.payroll_reimbursements pr
           where pr.payroll_id=p.id and pr.source_type='ACCESSORY_BOM' and pr.source_id is not null
  loop
    update erp.contractor_accessory_reimbursement_entitlements e
    set payroll_status=case
      when exists(select 1 from erp.payroll_reimbursements pr2 join erp.payroll_settlements ps2 on ps2.id=pr2.payroll_id
                  where pr2.source_type='ACCESSORY_BOM' and pr2.source_id=e.id and ps2.status='PAID') then 'SETTLED'
      when exists(select 1 from erp.payroll_reimbursements pr2 join erp.payroll_settlements ps2 on ps2.id=pr2.payroll_id
                  where pr2.source_type='ACCESSORY_BOM' and pr2.source_id=e.id and ps2.status<>'REVERSED') then 'ALLOCATED'
      else 'UNALLOCATED' end
    where e.id=r.id;
  end loop;
  for r in
    select distinct bc.id as bs_case_id from erp.bs_cases bc
    where exists(select 1 from erp.payroll_work_items pwi where pwi.payroll_id=p.id and pwi.po_id=bc.po_id)
       or exists(select 1 from erp.payroll_work_items pwi join erp.rework_component_lines rcl on rcl.id=pwi.source_id
                 join erp.bs_case_components bcc on bcc.id=rcl.bs_case_component_id
                 where pwi.payroll_id=p.id and bcc.bs_case_id=bc.id)
  loop perform erp.rebuild_bs_component_counters(r.bs_case_id); end loop;
  insert into erp.audit_logs(entity_type,entity_id,action,new_data,changed_by,change_reason)
  values('payroll_settlements',p.id,'REVERSE_PAID',jsonb_build_object('previous_status','PAID'),erp.current_app_user_id(),p_reason);
end;
$function$

definitions.erp._cp3_r4_active_pool_affects_contract:
CREATE OR REPLACE FUNCTION erp._cp3_r4_active_pool_affects_contractor(p_contractor_id uuid, p_effective_from date, p_next_effective_from date DEFAULT NULL::date)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  r record;
  v_sql text;
  v_hit boolean;
  v_join text;
  v_contractor_expr text;
begin
  if p_contractor_id is null or p_effective_from is null then
    raise exception 'R4 active-pool policy overlap requires contractor and effective_from';
  end if;

  for r in
    select c.table_name
    from information_schema.columns c
    where c.table_schema='erp'
      and c.column_name='pool_id'
      and c.table_name like 'attendance_hpp_pool_%'
    group by c.table_name
    order by c.table_name
  loop
    v_join:='';
    v_contractor_expr:=null;

    if exists(select 1 from information_schema.columns c where c.table_schema='erp' and c.table_name=r.table_name and c.column_name='contractor_id') then
      v_contractor_expr:='x.contractor_id';
    elsif exists(select 1 from information_schema.columns c where c.table_schema='erp' and c.table_name=r.table_name and c.column_name='payroll_id') then
      v_join:=' join erp.payroll_settlements ps on ps.id=x.payroll_id ';
      v_contractor_expr:='ps.contractor_id';
    elsif exists(select 1 from information_schema.columns c where c.table_schema='erp' and c.table_name=r.table_name and c.column_name='source_payroll_id') then
      v_join:=' join erp.payroll_settlements ps on ps.id=x.source_payroll_id ';
      v_contractor_expr:='ps.contractor_id';
    elsif exists(select 1 from information_schema.columns c where c.table_schema='erp' and c.table_name=r.table_name and c.column_name='payroll_settlement_id') then
      v_join:=' join erp.payroll_settlements ps on ps.id=x.payroll_settlement_id ';
      v_contractor_expr:='ps.contractor_id';
    elsif exists(select 1 from information_schema.columns c where c.table_schema='erp' and c.table_name=r.table_name and c.column_name='sewing_terminal_event_id') then
      v_join:=' join erp.sewing_terminal_events ste on ste.id=x.sewing_terminal_event_id ';
      v_contractor_expr:='ste.contractor_id';
    elsif exists(select 1 from information_schema.columns c where c.table_schema='erp' and c.table_name=r.table_name and c.column_name='destination_event_id') then
      v_join:=' join erp.sewing_terminal_events ste on ste.id=x.destination_event_id ';
      v_contractor_expr:='ste.contractor_id';
    elsif exists(select 1 from information_schema.columns c where c.table_schema='erp' and c.table_name=r.table_name and c.column_name='source_journal_line_id') then
      v_join:=' join erp.journal_lines jl on jl.id=x.source_journal_line_id join erp.journal_entries je on je.id=jl.journal_entry_id join erp.payroll_settlements ps on ps.id=je.source_id ';
      v_contractor_expr:='ps.contractor_id';
    elsif exists(select 1 from information_schema.columns c where c.table_schema='erp' and c.table_name=r.table_name and c.column_name='original_payroll_debit_journal_line_id') then
      v_join:=' join erp.journal_lines jl on jl.id=x.original_payroll_debit_journal_line_id join erp.journal_entries je on je.id=jl.journal_entry_id join erp.payroll_settlements ps on ps.id=je.source_id ';
      v_contractor_expr:='ps.contractor_id';
    end if;

    if v_contractor_expr is not null then
      v_sql:=format(
        'select exists(select 1 from erp.%I x join erp.attendance_hpp_pools p on p.id=x.pool_id %s where p.status=''ACTIVE'' and p.period_end >= $2 and ($3 is null or p.period_start < $3) and %s=$1)',
        r.table_name,v_join,v_contractor_expr
      );
      execute v_sql into v_hit using p_contractor_id,p_effective_from,p_next_effective_from;
      if v_hit then return true; end if;
    end if;
  end loop;

  return false;
end
$function$

definitions.erp.reverse_journal(uuid,text):
CREATE OR REPLACE FUNCTION erp.reverse_journal(p_journal_entry_id uuid, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare v_source_type text;
begin
  perform erp.require_internal();
  if nullif(btrim(p_reason),'') is null then raise exception 'Journal reversal reason is required'; end if;
  select source_type into v_source_type
  from erp.journal_entries where id=p_journal_entry_id for update;
  if v_source_type is null then raise exception 'Journal entry not found'; end if;
  if v_source_type='POCKET_HPP_PERIOD' then raise exception 'Batalkan alokasi kain kantong melalui periode asal';end if;
  if v_source_type='MATERIAL_ADJUSTMENT' and exists(select 1 from erp.pocket_fabric_usage u join erp.journal_entries j on j.source_id=u.adjustment_id where j.id=p_journal_entry_id)
    and not exists(select 1 from erp.pocket_fabric_execution_context c join erp.journal_entries j on j.source_id=c.adjustment_id
      where c.backend_pid=pg_backend_pid() and c.transaction_id=txid_current()
      and c.actor_key=erp._idempotency_actor_key() and j.id=p_journal_entry_id) then
    raise exception 'Batalkan pengurangan kain kantong melalui dokumen asal';end if;
  if v_source_type in('OPENING_PREPAYMENT','PREPAYMENT_EVENT') or (v_source_type in('SUPPLIER_PAYMENT','SALES_PAYMENT','VENDOR_PAYMENT','OPENING_SUBLEDGER_SETTLEMENT')
    and exists(select 1 from erp.initial_import_prepayment_payments l join erp.journal_entries j on j.source_id=l.payment_id where j.id=p_journal_entry_id)) then
    raise exception 'Pembatalan uang muka harus melalui sumber pembayaran atau perubahan tertaut';end if;
  if v_source_type='MATERIAL_ADJUSTMENT_REVALUATION' then
    raise exception 'T_PROTECTED_REVALUATION_JOURNAL_USE_SOURCE_WORKFLOW';
  end if;
  if v_source_type in ('ATTENDANCE_HPP_POOL','PAYROLL_ATTENDANCE_ACCRUAL') then
    raise exception 'Protected journal source type % cannot be reversed through generic reverse_journal. Use the owning attendance HPP pool or payroll cancellation/reversal flow.',v_source_type;
  end if;
  return erp._cp3_r4_reverse_journal_internal(p_journal_entry_id,p_reason);
end
$function$

definitions.erp.record_sewing_terminal_v1(jsonb,uuid:
CREATE OR REPLACE FUNCTION erp.record_sewing_terminal_v1(p_payload jsonb, p_client_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_operation constant text := 'record_sewing_terminal_v1';
  v_hash text;
  v_cached jsonb;
  v_work_completion_id uuid;
  v_qty integer;
  v_reason text;
  v_work erp.work_completion_events%rowtype;
  v_max_line_qty integer;
  v_cutting_qty bigint;
  v_existing_terminal_qty bigint;
  v_event erp.sewing_terminal_events%rowtype;
  v_response jsonb;
begin
  perform erp.require_internal();
  perform erp._cp3_assert_closed_json_object(
    p_payload,
    array['work_completion_id','qty_pcs','reason'],
    array['work_completion_id','qty_pcs','reason'],
    'SELESAI_DIJAHIT payload'
  );

  if jsonb_typeof(p_payload->'work_completion_id') is distinct from 'string'
     or jsonb_typeof(p_payload->'qty_pcs') is distinct from 'number'
     or jsonb_typeof(p_payload->'reason') is distinct from 'string' then
    raise exception 'SELESAI_DIJAHIT payload has invalid field types';
  end if;

  v_work_completion_id := (p_payload->>'work_completion_id')::uuid;
  v_qty := (p_payload->>'qty_pcs')::integer;
  v_reason := nullif(btrim(p_payload->>'reason'), '');

  if v_qty <= 0 then raise exception 'SELESAI_DIJAHIT qty must be positive'; end if;
  if v_reason is null then raise exception 'SELESAI_DIJAHIT reason is required'; end if;

  v_hash := erp._request_hash(jsonb_build_object('payload', p_payload));
  v_cached := erp._idempotency_begin(v_operation, p_client_request_id, v_hash);
  if v_cached is not null then return v_cached; end if;

  select * into v_work
  from erp.work_completion_events
  where id = v_work_completion_id
  for update;

  if v_work.id is null then raise exception 'Work completion not found'; end if;
  if v_work.status <> 'POSTED' then
    raise exception 'SELESAI_DIJAHIT can only reference a POSTED production work completion';
  end if;

  perform erp._cp3_lock_business_date(erp._cp3_business_date(v_work.physical_at));
  if exists (
    select 1 from erp.attendance_hpp_pools p
    where p.status = 'ACTIVE'
      and erp._cp3_business_date(v_work.physical_at) between p.period_start and p.period_end
  ) then
    raise exception 'ACTIVE_ATTENDANCE_HPP_PERIOD_LOCKED: cancel the active pool before recording late/backdated SELESAI_DIJAHIT';
  end if;
  if v_work.cutting_group_id is null then
    raise exception 'SELESAI_DIJAHIT requires cutting-group lineage';
  end if;
  if not exists (
    select 1 from erp.contractors c
    where c.id = v_work.contractor_id and c.contractor_type = 'MANDOR'
  ) then
    raise exception 'SELESAI_DIJAHIT source contractor must have explicit role MANDOR';
  end if;
  if exists (
    select 1 from erp.sewing_terminal_events e
    where e.source_work_completion_id = v_work.id
      and e.event_kind = 'SELESAI_DIJAHIT'
  ) then
    raise exception 'This work completion already has an authoritative SELESAI_DIJAHIT event';
  end if;

  select max(l.qty_completed)::integer into v_max_line_qty
  from erp.work_completion_lines l
  where l.completion_id = v_work.id;

  if coalesce(v_max_line_qty, 0) <= 0 or v_qty > v_max_line_qty then
    raise exception 'SELESAI_DIJAHIT qty % exceeds the maximum completed qty % recorded by the owning work completion',
      v_qty, coalesce(v_max_line_qty, 0);
  end if;

  perform 1 from erp.cutting_groups where id = v_work.cutting_group_id for update;
  select coalesce(v.total_pcs, 0)::bigint into v_cutting_qty
  from erp.v_cutting_group_totals v
  where v.cutting_group_id = v_work.cutting_group_id;

  select coalesce(sum(e.qty_signed), 0)::bigint into v_existing_terminal_qty
  from erp.sewing_terminal_events e
  where e.cutting_group_id = v_work.cutting_group_id;

  if v_existing_terminal_qty + v_qty > coalesce(v_cutting_qty, 0) then
    raise exception 'Cumulative SELESAI_DIJAHIT qty would exceed cutting-group physical qty. Current %, new %, maximum %',
      v_existing_terminal_qty, v_qty, coalesce(v_cutting_qty, 0);
  end if;

  insert into erp.sewing_terminal_events(
    event_number, event_kind, source_work_completion_id,
    contractor_id, po_id, cutting_group_id, physical_at,
    qty_signed, reason, created_by
  ) values (
    'SEW-' || to_char(v_work.physical_at at time zone 'UTC', 'YYYYMMDDHH24MISSUS') || '-' || substr(gen_random_uuid()::text, 1, 8),
    'SELESAI_DIJAHIT', v_work.id,
    v_work.contractor_id, v_work.po_id, v_work.cutting_group_id, v_work.physical_at,
    v_qty, v_reason, erp.current_app_user_id()
  ) returning * into v_event;

  insert into erp.audit_logs(entity_type, entity_id, action, new_data, changed_by, change_reason)
  values (
    'sewing_terminal_events', v_event.id, 'POST',
    jsonb_build_object(
      'event_kind', v_event.event_kind,
      'source_work_completion_id', v_event.source_work_completion_id,
      'contractor_id', v_event.contractor_id,
      'po_id', v_event.po_id,
      'cutting_group_id', v_event.cutting_group_id,
      'physical_at_epoch_us', erp._cp3_epoch_microseconds(v_event.physical_at),
      'qty_signed', v_event.qty_signed
    ),
    erp.current_app_user_id(), v_reason
  );

  v_response := jsonb_build_object(
    'sewing_terminal_event_id', v_event.id,
    'event_number', v_event.event_number,
    'event_kind', v_event.event_kind,
    'source_work_completion_id', v_event.source_work_completion_id,
    'physical_at_epoch_us', erp._cp3_epoch_microseconds(v_event.physical_at),
    'qty_pcs', v_event.qty_signed,
    'row_version', v_event.row_version
  );
  return erp._idempotency_complete(v_operation, p_client_request_id, v_response);
end;
$function$

definitions.erp.set_contractor_hpp_policy_v1(jsonb,u:
CREATE OR REPLACE FUNCTION erp.set_contractor_hpp_policy_v1(p_payload jsonb, p_client_request_id uuid, p_expected_policy_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'auth', 'extensions', 'pg_temp'
AS $function$
declare
  v_operation constant text := 'set_contractor_hpp_policy_v1';
  v_hash text;
  v_cached jsonb;
  v_contractor_id uuid;
  v_effective_from date;
  v_is_special boolean;
  v_attendance_required boolean;
  v_reason text;
  v_contractor erp.contractors%rowtype;
  v_current erp.contractor_hpp_policy_versions%rowtype;
  v_next_from date;
  v_new erp.contractor_hpp_policy_versions%rowtype;
  v_response jsonb;
begin
  perform erp.require_owner_admin();
  perform erp._cp3_assert_closed_json_object(
    p_payload,
    array['contractor_id','effective_from','is_special','attendance_required','reason'],
    array['contractor_id','effective_from','is_special','attendance_required','reason'],
    'contractor HPP policy payload'
  );

  if jsonb_typeof(p_payload->'contractor_id') is distinct from 'string'
     or jsonb_typeof(p_payload->'effective_from') is distinct from 'string'
     or jsonb_typeof(p_payload->'is_special') is distinct from 'boolean'
     or jsonb_typeof(p_payload->'attendance_required') is distinct from 'boolean'
     or jsonb_typeof(p_payload->'reason') is distinct from 'string' then
    raise exception 'contractor HPP policy payload has invalid field types';
  end if;

  v_contractor_id := (p_payload->>'contractor_id')::uuid;
  v_effective_from := erp._cp3_parse_canonical_date(p_payload->>'effective_from', 'contractor HPP policy effective_from');
  v_is_special := (p_payload->>'is_special')::boolean;
  v_attendance_required := (p_payload->>'attendance_required')::boolean;
  v_reason := nullif(btrim(p_payload->>'reason'), '');

  if v_reason is null then raise exception 'HPP policy reason is required'; end if;
  if v_effective_from is null then raise exception 'effective_from is required'; end if;

  v_hash := erp._request_hash(jsonb_build_object(
    'payload', p_payload,
    'expected_policy_id', p_expected_policy_id
  ));
  v_cached := erp._idempotency_begin(v_operation, p_client_request_id, v_hash);
  if v_cached is not null then return v_cached; end if;

  perform pg_advisory_xact_lock(hashtextextended('CONTRACTOR_HPP_POLICY|' || v_contractor_id::text, 0));

  select * into v_contractor
  from erp.contractors
  where id = v_contractor_id
  for update;

  if v_contractor.id is null then raise exception 'Contractor not found'; end if;
  if v_contractor.contractor_type <> 'MANDOR' then
    raise exception 'Attendance HPP policy is only valid for role MANDOR';
  end if;
  if v_contractor.attendance_required is distinct from v_attendance_required then
    raise exception 'attendance_required payload must explicitly match contractor master; update master first, then write a new HPP policy version';
  end if;

  select * into v_current
  from erp.contractor_hpp_policy_versions p
  where p.contractor_id = v_contractor_id
    and v_effective_from >= p.effective_from
    and (p.effective_to is null or v_effective_from <= p.effective_to)
  order by p.effective_from desc, p.id desc
  limit 1
  for update;

  if v_current.id is distinct from p_expected_policy_id then
    raise exception 'STALE_POLICY expected %, current %', p_expected_policy_id, v_current.id;
  end if;
  if v_current.effective_from = v_effective_from then
    raise exception 'A contractor HPP policy already starts on this date';
  end if;

  select min(p.effective_from) into v_next_from
  from erp.contractor_hpp_policy_versions p
  where p.contractor_id = v_contractor_id
    and p.effective_from > v_effective_from;

  if erp._cp3_r4_active_pool_affects_contractor(v_contractor_id,v_effective_from,v_next_from) then
    raise exception 'Contractor HPP policy effective from % overlaps an ACTIVE attendance HPP pool. Cancel the ACTIVE pool first, then write the new policy version.',v_effective_from;
  end if;

  update erp.contractor_hpp_policy_versions p
  set effective_to = v_effective_from - 1,
      row_version = row_version + 1
  where p.contractor_id = v_contractor_id
    and p.effective_from < v_effective_from
    and (p.effective_to is null or p.effective_to >= v_effective_from);

  insert into erp.contractor_hpp_policy_versions(
    contractor_id, effective_from, effective_to,
    contractor_role_snapshot, attendance_required_snapshot,
    is_special, reason, created_by
  ) values (
    v_contractor_id, v_effective_from,
    case when v_next_from is null then null else v_next_from - 1 end,
    'MANDOR', v_attendance_required,
    v_is_special, v_reason, erp.current_app_user_id()
  ) returning * into v_new;

  -- HPP01 (CP1-CP7 audit fix, cp7_hpp_policy_guard_bundle.py): a policy write that changes the basis of an ACTIVE
  -- attendance HPP pool, by this contractor, is refused; cancel that pool first, then write the policy.
  perform 1 from erp.attendance_hpp_pools hp
   where hp.status='ACTIVE'
     and hp.period_end>=least(v_current.effective_from,v_effective_from)
     and erp._build_attendance_hpp_manifest_v1(hp.period_start,hp.period_end) is distinct from hp.source_manifest
     and (jsonb_path_exists(hp.source_manifest,'$.**.contractor_id ? (@ == $c)',jsonb_build_object('c',v_contractor_id))
      or jsonb_path_exists(erp._build_attendance_hpp_manifest_v1(hp.period_start,hp.period_end),'$.**.contractor_id ? (@ == $c)',jsonb_build_object('c',v_contractor_id)));
  if found then
    raise exception 'CP7_HPP_POLICY_CHANGES_ACTIVE_POOL: kebijakan HPP mandor ini mengubah dasar pool HPP absensi yang sudah AKTIF. Batalkan pool itu dulu, lalu simpan kebijakan dan buat pool pengganti.';
  end if;

  insert into erp.audit_logs(entity_type, entity_id, action, new_data, changed_by, change_reason)
  values (
    'contractor_hpp_policy_versions', v_new.id, 'INSERT',
    jsonb_build_object(
      'contractor_id', v_new.contractor_id,
      'effective_from', v_new.effective_from,
      'effective_to', v_new.effective_to,
      'contractor_role_snapshot', v_new.contractor_role_snapshot,
      'attendance_required_snapshot', v_new.attendance_required_snapshot,
      'is_special', v_new.is_special
    ),
    erp.current_app_user_id(), v_reason
  );

  v_response := jsonb_build_object(
    'policy_version_id', v_new.id,
    'contractor_id', v_new.contractor_id,
    'effective_from', v_new.effective_from,
    'effective_to', v_new.effective_to,
    'contractor_role_snapshot', v_new.contractor_role_snapshot,
    'attendance_required_snapshot', v_new.attendance_required_snapshot,
    'is_special', v_new.is_special,
    'row_version', v_new.row_version
  );
  return erp._idempotency_complete(v_operation, p_client_request_id, v_response);
end;
$function$

definitions.cp7_payroll.apply_settlement(text,jsonb,:
CREATE OR REPLACE FUNCTION cp7_payroll.apply_settlement(p_action text,p_payload jsonb,p_expected text) returns jsonb
language plpgsql volatile security definer set search_path='' as $$
declare p erp.payroll_settlements;a jsonb;before_meaning jsonb;after_meaning jsonb;prior_work jsonb;reason text:=btrim(p_payload->>'change_reason');
begin
 a:=cp7_payroll.settlement_access(p_action);
 select * into p from erp.payroll_settlements where id=(p_payload->>'id')::uuid for update;
 if p.id is null then raise exception 'CP7_PAYROLL_MISSING';end if;
 perform cp7_payroll.require_settlement_context(p.id);
 perform pg_advisory_xact_lock(hashtextextended(p.contractor_id::text,0));
 -- Native child writers use the payroll lock. These locks also fence edits to
 -- already selected rows while the review token is checked.
 perform 1 from erp.payroll_work_items where payroll_id=p.id order by id for update;
 perform 1 from erp.payroll_attendance_items where payroll_id=p.id order by id for update;
 perform 1 from erp.payroll_reimbursements where payroll_id=p.id order by id for update;
 perform 1 from erp.payroll_deductions where payroll_id=p.id order by id for update;
 if cp7_payroll.settlement_access(p_action) is distinct from a then raise exception using errcode='42501',message='CP7_PAYROLL_ACCESS_CHANGED';end if;
 if p.row_version::text is distinct from p_expected or cp7_payroll.settlement_token(p.id) is distinct from p_payload->>'review_token' then raise exception 'CP7_PAYROLL_REVIEW_CHANGED';end if;
 perform set_config('app.change_reason',reason,true);
 if p_action in('PREPARE','APPROVE') then
  if p.status not in('DRAFT','CALCULATED','REVIEW') then raise exception 'CP7_PAYROLL_DRAFT_ONLY';end if;
  -- Freeze existing source rows in native lock order. A new source visible
  -- before this rebuild is included and forces another review at APPROVE.
  perform 1 from erp.contractors where id=p.contractor_id for share;
  perform 1 from erp.attendance_periods where contractor_id=p.contractor_id and period_start<=p.period_end and period_end>=p.period_start order by id for share;
  perform 1 from erp.contractor_workers where contractor_id=p.contractor_id order by id for share;
  perform 1 from erp.attendance_records where contractor_id=p.contractor_id and attendance_date between p.period_start and p.period_end order by id for share;
  perform 1 from erp.contractor_accessory_reimbursement_entitlements where contractor_id=p.contractor_id order by id for update;
  perform 1 from erp.contractor_material_issues where contractor_id=p.contractor_id order by id for share;
  perform 1 from erp.contractor_material_issue_items i where exists(select 1 from erp.contractor_material_issues h where h.id=i.issue_id and h.contractor_id=p.contractor_id) order by i.id for update;
  before_meaning:=cp7_payroll.settlement_meaning(p.id);prior_work:=before_meaning->'work';
  -- Derived from the accepted populate function, with only automatic work
  -- removal/insertion removed. All non-work eligibility/formulas are identical.
  perform cp7_payroll.rebuild_nonwork(p.id);
  after_meaning:=cp7_payroll.settlement_meaning(p.id);
  if after_meaning->'work' is distinct from prior_work then raise exception 'CP7_PAYROLL_SELECTED_WORK_CHANGED';end if;
  if p_action='APPROVE' then
   if before_meaning is distinct from after_meaning then raise exception 'CP7_PAYROLL_PREPARE_REQUIRED: sumber atau jumlah berubah; hitung dan periksa ulang';end if;
   perform erp.approve_payroll(p.id);
  end if;
 elsif p_action='PAY' then
  if p.status<>'APPROVED' then raise exception 'CP7_PAYROLL_APPROVED_ONLY';end if;
  update erp.payroll_settlements set payment_date=(p_payload->>'payment_date')::date,payment_cash_account_id=(p_payload->>'cash_account_id')::uuid where id=p.id;
  -- FIN01/D14-2: the payment-date rule is reported before any cash posting
  -- (the PAID-transition trigger repeats it for every other caller).
  perform cp7_payroll.assert_payment_date(p.id,(p_payload->>'payment_date')::date);
  perform erp.post_payroll_payment(p.id);
 elsif p_action='CANCEL' then
  if p.status not in('DRAFT','CALCULATED','REVIEW','APPROVED') then raise exception 'CP7_PAYROLL_UNPAID_ONLY';end if;
  perform erp.cancel_unpaid_payroll(p.id,reason);
 elsif p_action='REVERSE' then
  if p.status<>'PAID' then raise exception 'CP7_PAYROLL_PAID_ONLY';end if;
  perform erp.reverse_paid_payroll(p.id,reason);
 else raise exception 'CP7_PAYROLL_ACTION';end if;
 if cp7_payroll.settlement_access(p_action) is distinct from a then raise exception using errcode='42501',message='CP7_PAYROLL_ACCESS_CHANGED';end if;
 return cp7_payroll.settlement_document(p.id);
end $$;

definitions.cp7_hpp_pool.pool_json(erp.attendance_hp:
CREATE OR REPLACE FUNCTION cp7_hpp_pool.pool_json(p_pool erp.attendance_hpp_pools,p_closed date)returns jsonb
language plpgsql volatile security definer set search_path=''as $$
declare v_alloc jsonb;v_po_count integer;v_sources integer;v_correction jsonb;v_replaced jsonb;v_open boolean;v_stale text;v_actions text[]:='{}';
 v_closed boolean;v_activation text;v_journal text;v_reversal text;
begin
 v_closed:=p_closed is not null and p_pool.period_end<=p_closed;
 select count(*)::integer into v_sources from erp.attendance_hpp_pool_sources ps where ps.pool_id=p_pool.id;
 select count(*)::integer,coalesce(jsonb_agg(jsonb_build_object('po_id',ay.po_id,'po_number',ay.po_number,'sewing_qty',ay.qty,'amount',ay.amount)order by ay.n)
   filter(where ay.n<=20),'[]'::jsonb)
  into v_po_count,v_alloc
  from(select ag.po_id,po.po_number,ag.qty,ag.amount,row_number()over(order by po.po_number,ag.po_id)n
   from(select al.po_id,sum(al.sewing_qty)::bigint qty,sum(al.allocated_amount)::numeric(20,2)::text amount
    from erp.attendance_hpp_pool_allocations al where al.pool_id=p_pool.id group by al.po_id)ag
   left join erp.production_orders po on po.id=ag.po_id)ay;
 select jsonb_build_object('id',hp.id,'pool_number',hp.pool_number,'status',hp.status)into v_correction
  from erp.attendance_hpp_pools hp where hp.id=p_pool.correction_of_pool_id;
 select coalesce(jsonb_agg(jsonb_build_object('id',rx.id,'pool_number',rx.pool_number,'status',rx.status)order by rx.created_at,rx.id),'[]'::jsonb)into v_replaced
  from(select hp.id,hp.pool_number,hp.status,hp.created_at from erp.attendance_hpp_pools hp where hp.correction_of_pool_id=p_pool.id
   order by hp.created_at,hp.id limit 5)rx;
 v_open:=exists(select 1 from erp.attendance_hpp_pools hp where hp.id<>p_pool.id and hp.period_start=p_pool.period_start
  and hp.period_end=p_pool.period_end and hp.status in('DRAFT','ACTIVE'));
 select lg.change_reason into v_activation from erp.audit_logs lg where lg.entity_type='attendance_hpp_pools'and lg.entity_id=p_pool.id
  and lg.new_data->>'lifecycle_action'='ACTIVATE' order by lg.changed_at desc,lg.id desc limit 1;
 select je.journal_number into v_journal from erp.journal_entries je where je.id=p_pool.post_journal_entry_id;
 select je.journal_number into v_reversal from erp.journal_entries je where je.id=p_pool.cancellation_journal_entry_id;
 if p_pool.status='DRAFT'then
  begin
   perform erp.validate_attendance_hpp_pool_v1(p_pool.id);
  exception when raise_exception then v_stale:=left(sqlerrm,500);
  end;
 end if;
 if not v_closed then
  if p_pool.status='DRAFT'then v_actions:=case when v_stale is null then array['ACTIVATE','CANCEL']else array['CANCEL']end;
  elsif p_pool.status='ACTIVE'then v_actions:=array['CANCEL'];
  elsif p_pool.status='CANCELLED'and not v_open then v_actions:=array['REPLACE'];
  end if;
 end if;
 return jsonb_build_object('id',p_pool.id,'pool_number',p_pool.pool_number,'status',p_pool.status,'period_start',p_pool.period_start,
  'period_end',p_pool.period_end,'numerator_amount',p_pool.numerator_amount::text,'denominator_qty',p_pool.denominator_qty,
  'unit_cost_per_sewn_pcs',p_pool.unit_cost_per_sewn_pcs::text,'source_count',v_sources,'po_count',v_po_count,'allocations',v_alloc,
  'correction_of',v_correction,'replaced_by',v_replaced,
  'created_at',cp7_hpp_pool.iso(p_pool.created_at),'created_by',(select u.full_name from erp.app_users u where u.id=p_pool.created_by),
  'reason',p_pool.reason,
  'activated_at',cp7_hpp_pool.iso(p_pool.activated_at),'activated_by',(select u.full_name from erp.app_users u where u.id=p_pool.activated_by),
  'activation_reason',v_activation,
  'cancelled_at',cp7_hpp_pool.iso(p_pool.cancelled_at),'cancelled_by',(select u.full_name from erp.app_users u where u.id=p_pool.cancelled_by),
  'cancellation_reason',p_pool.cancellation_reason,'journal_number',v_journal,'reversal_journal_number',v_reversal,
  'row_version',p_pool.row_version,'review_token',cp7_hpp_pool.pool_token(p_pool),'period_closed',v_closed,
  'stale',v_stale is not null,'stale_message',v_stale,'actions',to_jsonb(v_actions));
end $$;

definitions.cp7_hpp_pool.preview(date,date,date):
CREATE OR REPLACE FUNCTION cp7_hpp_pool.preview(p_start date,p_end date,p_closed date)returns jsonb
language plpgsql volatile security definer set search_path=''as $$
declare v_native jsonb;v_message text;v_code text;v_existing jsonb;v_cancelled jsonb;v_pos jsonb;v_po_count integer;v_numerator text;
 v_denominator bigint;v_unit text;v_sha text;v_period_closed boolean;
begin
 v_period_closed:=p_closed is not null and p_end<=p_closed;
 select jsonb_build_object('id',hp.id,'pool_number',hp.pool_number,'status',hp.status)into v_existing
  from erp.attendance_hpp_pools hp where hp.period_start=p_start and hp.period_end=p_end and hp.status in('DRAFT','ACTIVE')
  order by hp.created_at desc,hp.id desc limit 1;
 select coalesce(jsonb_agg(jsonb_build_object('id',cx.id,'pool_number',cx.pool_number)order by cx.created_at desc,cx.id desc),'[]'::jsonb)into v_cancelled
  from(select hp.id,hp.pool_number,hp.created_at from erp.attendance_hpp_pools hp where hp.period_start=p_start and hp.period_end=p_end
   and hp.status='CANCELLED' order by hp.created_at desc,hp.id desc limit 10)cx;
 begin
  v_native:=erp.preview_attendance_hpp_pool_v1(p_start,p_end);
 exception when raise_exception then
  v_message:=sqlerrm;v_native:=null;
 end;
 if v_native is null then
  v_code:=case when v_message like '%lack one explicit HPP policy%'then'MISSING_POLICY'
   when v_message like '%do not reconcile to immutable attendance items%'then'ATTENDANCE_MISMATCH'
   when v_message like '%lack one unambiguous WIP debit line%'then'JOURNAL_UNCLEAR'
   when v_message like 'No eligible normal-Mandor attendance payroll cost%'then'NO_ATTENDANCE_COST'
   when v_message like 'POSITIVE_POOL_ZERO_SEWING_OUTPUT%'then'NO_SEWING_OUTPUT'
   else'OTHER'end;
  return jsonb_build_object('period_start',p_start,'period_end',p_end,'status','BLOCKED','period_closed',v_period_closed,'existing_pool',v_existing,
   'cancelled_pools',v_cancelled,'numerator_amount',null,'denominator_qty',null,'unit_cost_per_sewn_pcs',null,'source_count',null,
   'destination_count',null,'po_count',null,'pos','[]'::jsonb,'manifest_sha256',null,'review_token',null,
   'blocker',jsonb_build_object('code',v_code,'message',left(coalesce(v_message,''),500)),'can_create',false);
 end if;
 if v_native->>'status'is distinct from'READY'or jsonb_typeof(v_native->'manifest')is distinct from'object'then
  raise exception 'CP7_HPP_POOL_PREVIEW_SHAPE';end if;
 v_sha:=v_native->>'manifest_sha256';
 -- Exactly what the Native create stores: numeric(20,2) and numeric(28,12) of the Native preview values.
 v_numerator:=((v_native->>'numerator_amount')::numeric(20,2))::text;
 v_denominator:=(v_native->>'denominator_qty')::bigint;
 v_unit:=((v_native->>'unit_cost_per_sewn_pcs')::numeric(28,12))::text;
 select count(*)::integer,coalesce(jsonb_agg(jsonb_build_object('po_id',py.po_id,'po_number',py.po_number,'sewing_qty',py.qty)order by py.n)filter(where py.n<=20),'[]'::jsonb)
  into v_po_count,v_pos
  from(select pd.po_id,po.po_number,pd.qty,row_number()over(order by po.po_number,pd.po_id)n
   from(select(dx->>'po_id')::uuid po_id,sum((dx->>'sewing_qty')::bigint)::bigint qty from jsonb_array_elements(v_native->'manifest'->'destinations')dx group by 1)pd
   left join erp.production_orders po on po.id=pd.po_id)py;
 return jsonb_build_object('period_start',p_start,'period_end',p_end,'status','READY','period_closed',v_period_closed,'existing_pool',v_existing,
  'cancelled_pools',v_cancelled,'numerator_amount',v_numerator,'denominator_qty',v_denominator,'unit_cost_per_sewn_pcs',v_unit,
  'source_count',jsonb_array_length(v_native->'manifest'->'sources'),'destination_count',jsonb_array_length(v_native->'manifest'->'destinations'),
  'po_count',v_po_count,'pos',v_pos,'manifest_sha256',v_sha,
  'review_token',cp7_hpp_pool.preview_token(p_start,p_end,v_sha,v_numerator,v_denominator,v_unit),'blocker',null,
  'can_create',not v_period_closed and v_existing is null);
end $$;

erp._assert_attendance_hpp_manifest_v1(j.definition:
CREATE OR REPLACE FUNCTION erp._assert_attendance_hpp_manifest_v1(p_manifest jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  v_item jsonb;
begin
  perform erp._cp3_assert_closed_json_object(
    p_manifest,
    array['contract_version','operation_type','period_start','period_end','numerator_cents','denominator_qty','sources','destinations'],
    array['contract_version','operation_type','period_start','period_end','numerator_cents','denominator_qty','sources','destinations'],
    'attendance HPP manifest'
  );

  if jsonb_typeof(p_manifest->'contract_version') is distinct from 'string'
     or jsonb_typeof(p_manifest->'operation_type') is distinct from 'string'
     or jsonb_typeof(p_manifest->'period_start') is distinct from 'string'
     or jsonb_typeof(p_manifest->'period_end') is distinct from 'string'
     or jsonb_typeof(p_manifest->'numerator_cents') is distinct from 'number'
     or jsonb_typeof(p_manifest->'denominator_qty') is distinct from 'number'
     or jsonb_typeof(p_manifest->'sources') is distinct from 'array'
     or jsonb_typeof(p_manifest->'destinations') is distinct from 'array' then
    raise exception 'Attendance HPP manifest has invalid top-level types';
  end if;

  if p_manifest->>'contract_version' is distinct from 'ATTENDANCE_HPP_SEWING_TERMINAL_V1'
     or p_manifest->>'operation_type' is distinct from 'ATTENDANCE_HPP_POOL' then
    raise exception 'Attendance HPP manifest discriminator is invalid; claim/transfer/carry-forward/movement payloads are not accepted';
  end if;
  if p_manifest->>'period_start' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
     or p_manifest->>'period_end' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then
    raise exception 'Attendance HPP manifest period dates must be canonical YYYY-MM-DD strings';
  end if;

  for v_item in select value from jsonb_array_elements(p_manifest->'sources')
  loop
    perform erp._cp3_assert_closed_json_object(
      v_item,
      array['payroll_id','contractor_id','policy_version_id','contractor_role_snapshot','attendance_required_snapshot','is_special_snapshot','policy_effective_from','original_debit_journal_line_id','original_debit_amount_cents','attendance_amount_cents'],
      array['payroll_id','contractor_id','policy_version_id','contractor_role_snapshot','attendance_required_snapshot','is_special_snapshot','policy_effective_from','policy_effective_to','original_debit_journal_line_id','original_debit_amount_cents','attendance_amount_cents'],
      'attendance HPP source'
    );
    if not (v_item ? 'policy_effective_to') then
      raise exception 'attendance HPP source requires key policy_effective_to, which may be JSON null for open-ended coverage';
    end if;
    if jsonb_typeof(v_item->'payroll_id') is distinct from 'string'
       or jsonb_typeof(v_item->'contractor_id') is distinct from 'string'
       or jsonb_typeof(v_item->'policy_version_id') is distinct from 'string'
       or jsonb_typeof(v_item->'contractor_role_snapshot') is distinct from 'string'
       or jsonb_typeof(v_item->'attendance_required_snapshot') is distinct from 'boolean'
       or jsonb_typeof(v_item->'is_special_snapshot') is distinct from 'boolean'
       or jsonb_typeof(v_item->'policy_effective_from') is distinct from 'string'
       or (v_item->'policy_effective_to' <> 'null'::jsonb
           and jsonb_typeof(v_item->'policy_effective_to') is distinct from 'string')
       or jsonb_typeof(v_item->'original_debit_journal_line_id') is distinct from 'string'
       or jsonb_typeof(v_item->'original_debit_amount_cents') is distinct from 'number'
       or jsonb_typeof(v_item->'attendance_amount_cents') is distinct from 'number' then
      raise exception 'attendance HPP source has invalid nested field types';
    end if;
    if v_item->>'contractor_role_snapshot' is distinct from 'MANDOR'
       or v_item->'attendance_required_snapshot' is distinct from 'true'::jsonb
       or v_item->'is_special_snapshot' is distinct from 'false'::jsonb then
      raise exception 'Attendance HPP source is not an eligible normal Mandor snapshot';
    end if;
    if v_item->>'policy_effective_from' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
       or (v_item->'policy_effective_to' <> 'null'::jsonb
           and v_item->>'policy_effective_to' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$') then
      raise exception 'attendance HPP source policy dates must be canonical YYYY-MM-DD strings';
    end if;
  end loop;

  for v_item in select value from jsonb_array_elements(p_manifest->'destinations')
  loop
    perform erp._cp3_assert_closed_json_object(
      v_item,
      array['sewing_terminal_event_id','source_work_completion_id','contractor_id','po_id','cutting_group_id','policy_version_id','contractor_role_snapshot','attendance_required_snapshot','is_special_snapshot','physical_at_epoch_us','sewing_qty'],
      array['sewing_terminal_event_id','source_work_completion_id','contractor_id','po_id','cutting_group_id','policy_version_id','contractor_role_snapshot','attendance_required_snapshot','is_special_snapshot','physical_at_epoch_us','sewing_qty'],
      'attendance HPP destination'
    );
    if jsonb_typeof(v_item->'sewing_terminal_event_id') is distinct from 'string'
       or jsonb_typeof(v_item->'source_work_completion_id') is distinct from 'string'
       or jsonb_typeof(v_item->'contractor_id') is distinct from 'string'
       or jsonb_typeof(v_item->'po_id') is distinct from 'string'
       or jsonb_typeof(v_item->'cutting_group_id') is distinct from 'string'
       or jsonb_typeof(v_item->'policy_version_id') is distinct from 'string'
       or jsonb_typeof(v_item->'contractor_role_snapshot') is distinct from 'string'
       or jsonb_typeof(v_item->'attendance_required_snapshot') is distinct from 'boolean'
       or jsonb_typeof(v_item->'is_special_snapshot') is distinct from 'boolean'
       or jsonb_typeof(v_item->'physical_at_epoch_us') is distinct from 'number'
       or jsonb_typeof(v_item->'sewing_qty') is distinct from 'number' then
      raise exception 'attendance HPP destination has invalid nested field types';
    end if;
    if v_item->>'contractor_role_snapshot' is distinct from 'MANDOR'
       or v_item->'attendance_required_snapshot' is distinct from 'true'::jsonb
       or v_item->'is_special_snapshot' is distinct from 'false'::jsonb then
      raise exception 'Attendance HPP destination is not an eligible normal Mandor snapshot';
    end if;
  end loop;
end;
$function$

erp.preview_attendance_hpp_pool_v1(date,.definition:
CREATE OR REPLACE FUNCTION erp.preview_attendance_hpp_pool_v1(p_period_start date, p_period_end date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  v_manifest jsonb;
  v_missing_policy_count bigint;
  v_bad_attendance_snapshot_count bigint;
  v_bad_journal_count bigint;
  v_numerator_cents bigint;
  v_denominator_qty bigint;
begin
  perform erp.require_internal();
  if p_period_start is null or p_period_end is null or p_period_end < p_period_start then
    raise exception 'Valid period_start and period_end are required';
  end if;

  select count(*) into v_missing_policy_count
  from erp.payroll_settlements ps
  join erp.contractors c on c.id = ps.contractor_id
  where ps.status in ('APPROVED','PAID')
    and ps.period_start = p_period_start
    and ps.period_end = p_period_end
    and ps.attendance_total > 0
    and c.contractor_type = 'MANDOR'
    and not exists (
      select 1
      from erp.contractor_hpp_policy_versions p
      where p.contractor_id = ps.contractor_id
        and p.effective_from <= p_period_start
        and (p.effective_to is null or p.effective_to >= p_period_end)
    );
  if v_missing_policy_count > 0 then
    raise exception '% approved/paid attendance payroll(s) lack one explicit HPP policy covering the full period', v_missing_policy_count;
  end if;

  select count(*) into v_bad_attendance_snapshot_count
  from erp.payroll_settlements ps
  where ps.status in ('APPROVED','PAID')
    and ps.period_start = p_period_start
    and ps.period_end = p_period_end
    and abs(ps.attendance_total - coalesce((
      select sum(pai.amount) from erp.payroll_attendance_items pai where pai.payroll_id = ps.id
    ), 0)) > 0.01;
  if v_bad_attendance_snapshot_count > 0 then
    raise exception '% payroll attendance total(s) do not reconcile to immutable attendance items', v_bad_attendance_snapshot_count;
  end if;

  select count(*) into v_bad_journal_count
  from erp.payroll_settlements ps
  join lateral (
    select count(*) as line_count, max(jl.debit) as debit_amount
    from erp.journal_entries je
    join erp.journal_lines jl on jl.journal_entry_id = je.id
    where je.source_id = ps.id
      and je.source_type = 'PAYROLL_ATTENDANCE_ACCRUAL'
      and je.status = 'POSTED'
      and jl.account_id = erp.account_id('WIP')
      and jl.debit > 0
  ) x on true
  where ps.status in ('APPROVED','PAID')
    and ps.period_start = p_period_start
    and ps.period_end = p_period_end
    and ps.attendance_total > 0
    and (x.line_count <> 1 or x.debit_amount + 0.01 < ps.attendance_total);
  if v_bad_journal_count > 0 then
    raise exception '% approved/paid attendance payroll(s) lack one unambiguous WIP debit line from PAYROLL_ATTENDANCE_ACCRUAL covering attendance amount', v_bad_journal_count;
  end if;

  v_manifest := erp._build_attendance_hpp_manifest_v1(p_period_start, p_period_end);
  perform erp._assert_attendance_hpp_manifest_v1(v_manifest);
  v_numerator_cents := (v_manifest->>'numerator_cents')::bigint;
  v_denominator_qty := (v_manifest->>'denominator_qty')::bigint;

  if v_numerator_cents <= 0 then
    raise exception 'No eligible normal-Mandor attendance payroll cost exists for this exact period';
  end if;
  if v_denominator_qty <= 0 then
    raise exception 'POSITIVE_POOL_ZERO_SEWING_OUTPUT: attendance cost exists but immutable SELESAI_DIJAHIT denominator is zero; keep cost unassigned/WIP and do not use QC GOOD fallback';
  end if;

  return jsonb_build_object(
    'status', 'READY',
    'manifest', v_manifest,
    'manifest_sha256', erp._cp3_manifest_sha256(v_manifest),
    'numerator_amount', v_numerator_cents / 100.0,
    'denominator_qty', v_denominator_qty,
    'unit_cost_per_sewn_pcs', (v_numerator_cents / 100.0) / v_denominator_qty
  );
end;
$function$

erp._cp3_parse_canonical_date(text,text).definition:
CREATE OR REPLACE FUNCTION erp._cp3_parse_canonical_date(p_value text, p_label text)
 RETURNS date
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  v_date date;
begin
  if p_value is null or p_value !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then
    raise exception '% must be a canonical YYYY-MM-DD string', coalesce(p_label,'date');
  end if;
  v_date := p_value::date;
  if to_char(v_date,'YYYY-MM-DD') is distinct from p_value then
    raise exception '% is not a real canonical calendar date', coalesce(p_label,'date');
  end if;
  return v_date;
exception when datetime_field_overflow or invalid_datetime_format then
  raise exception '% is not a real canonical calendar date', coalesce(p_label,'date');
end;
$function$

erp._cp3_assert_closed_json_object(jsonb.definition:
CREATE OR REPLACE FUNCTION erp._cp3_assert_closed_json_object(p_value jsonb, p_required_keys text[], p_allowed_keys text[], p_label text)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  v_key text;
begin
  if p_value is null or jsonb_typeof(p_value) is distinct from 'object' then
    raise exception '% must be a JSON object', coalesce(p_label, 'payload');
  end if;

  foreach v_key in array coalesce(p_required_keys, array[]::text[])
  loop
    if not (p_value ? v_key)
       or coalesce(jsonb_typeof(p_value -> v_key), 'missing') = 'null' then
      raise exception '% requires non-null key %', coalesce(p_label, 'payload'), v_key;
    end if;
  end loop;

  select k into v_key
  from jsonb_object_keys(p_value) as x(k)
  where not (k = any(coalesce(p_allowed_keys, array[]::text[])))
  order by k
  limit 1;

  if v_key is not null then
    raise exception '% contains unexpected key %', coalesce(p_label, 'payload'), v_key;
  end if;
end;
$function$

erp._cp3_lock_business_date(date).definition:
CREATE OR REPLACE FUNCTION erp._cp3_lock_business_date(p_business_date date)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
begin
  if p_business_date is null then raise exception 'CP3 business date lock requires a date'; end if;
  perform pg_advisory_xact_lock(hashtextextended(
    'ATTENDANCE_HPP_BUSINESS_DATE|' || erp._cp3_canonical_date(p_business_date), 0
  ));
end;
$function$

erp._cp3_lock_business_period(date,date).definition:
CREATE OR REPLACE FUNCTION erp._cp3_lock_business_period(p_period_start date, p_period_end date)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  v_day date;
begin
  if p_period_start is null or p_period_end is null or p_period_end < p_period_start then
    raise exception 'CP3 business period lock requires a valid date range';
  end if;
  if p_period_end - p_period_start > 366 then
    raise exception 'CP3 business period lock is bounded to 367 calendar days';
  end if;
  for v_day in
    select d::date from generate_series(p_period_start::timestamp, p_period_end::timestamp, interval '1 day') d order by 1
  loop
    perform erp._cp3_lock_business_date(v_day);
  end loop;
end;
$function$

erp._idempotency_begin(text,uuid,text).definition:
CREATE OR REPLACE FUNCTION erp._idempotency_begin(p_operation_name text, p_client_request_id uuid, p_request_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  v_actor text := erp._idempotency_actor_key();
  v_row erp.idempotency_requests%rowtype;
begin
  if p_client_request_id is null then
    raise exception 'client_request_id is required';
  end if;
  if coalesce(btrim(p_operation_name), '') = '' then
    raise exception 'operation_name is required';
  end if;

  insert into erp.idempotency_requests(
    actor_key, operation_name, client_request_id, request_hash
  ) values (
    v_actor, p_operation_name, p_client_request_id, p_request_hash
  )
  on conflict do nothing;

  select * into v_row
  from erp.idempotency_requests
  where actor_key = v_actor
    and operation_name = p_operation_name
    and client_request_id = p_client_request_id
  for update;

  if v_row.request_hash <> p_request_hash then
    raise exception 'client_request_id was already used with a different payload';
  end if;
  if v_row.status = 'COMPLETED' then
    return v_row.response_payload;
  end if;
  return null;
end;
$function$

erp.post_journal(text,uuid,date,text,jso.definition:
CREATE OR REPLACE FUNCTION erp.post_journal(p_source_type text, p_source_id uuid, p_transaction_date date, p_description text, p_lines jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  v_entry_id uuid;
  v_input_debit numeric;
  v_input_credit numeric;
  v_cent_lines jsonb := '[]'::jsonb;
  v_number text;
  v_debit numeric(20,2);
  v_credit numeric(20,2);
  r jsonb;
  v_account_id uuid;
  v_gl_date date;
  v_ap_vendor_account uuid;
  v_vendor_id uuid;
  v_vendor_balance numeric(24,6);
  v_vendor_delta numeric(24,6);
begin
  perform erp.require_internal();
  if jsonb_typeof(p_lines) is distinct from 'array' then
    raise exception 'JOURNAL_LINES_ARRAY_REQUIRED';
  end if;
  if jsonb_array_length(p_lines)<2 then
    raise exception 'Journal requires at least two lines';
  end if;
  -- Canonicalize each monetary line exactly as it will be stored. All balance
  -- and vendor-admission checks below consume these same cent amounts.
  for r in select * from jsonb_array_elements(p_lines) loop
    if jsonb_typeof(r) is distinct from 'object' then
      raise exception 'JOURNAL_LINE_OBJECT_REQUIRED';
    end if;
    v_input_debit:=coalesce((r->>'debit')::numeric,0);
    v_input_credit:=coalesce((r->>'credit')::numeric,0);
    if v_input_debit::text in('NaN','Infinity','-Infinity')
       or v_input_credit::text in('NaN','Infinity','-Infinity')
       or v_input_debit<0 or v_input_credit<0 then
      raise exception 'JOURNAL_FINITE_NONNEGATIVE_MONEY_REQUIRED';
    end if;
    v_cent_lines:=v_cent_lines||jsonb_build_array(r||jsonb_build_object(
      'debit',round(v_input_debit,2),'credit',round(v_input_credit,2)));
  end loop;
  p_lines:=v_cent_lines;
  select coalesce(sum(coalesce((x->>'debit')::numeric,0)),0),coalesce(sum(coalesce((x->>'credit')::numeric,0)),0)
  into v_debit,v_credit from jsonb_array_elements(p_lines) x;
  if v_debit<>v_credit or v_debit<=0 then raise exception 'Journal is not balanced. Debit %, Credit %',v_debit,v_credit; end if;
  if exists(select 1 from erp.journal_entries where source_type=p_source_type and source_id=p_source_id and status='POSTED') then
    raise exception 'A posted journal already exists for this source';
  end if;

  -- Serialize journal posting with accounting close/reopen. A close that starts
  -- first blocks this journal until the new closed-through date is visible; a
  -- journal that starts first keeps the close waiting until this posting commits.
  perform 1 from erp.accounting_period_control where singleton_id=1 for share;

  -- Vendor AP is allowed to reach zero, but not become negative. Negative AP
  -- means the company has a receivable/advance from the vendor and requires a
  -- separate explicit workflow instead of silently crossing the account sign.
  v_ap_vendor_account:=erp.account_id('AP_VENDOR');
  for v_vendor_id in
    select distinct nullif(x->>'vendor_id','')::uuid
    from jsonb_array_elements(p_lines) x
    where nullif(x->>'vendor_id','') is not null
      and coalesce((x->>'debit')::numeric,0)>coalesce((x->>'credit')::numeric,0)
      and (
        (x ? 'mapping_key' and x->>'mapping_key'='AP_VENDOR')
        or (x ? 'account_id' and nullif(x->>'account_id','')::uuid=v_ap_vendor_account)
      )
    order by 1
  loop
    perform pg_advisory_xact_lock(hashtextextended('VENDOR_AP|'||v_vendor_id::text,0));

    select coalesce(sum(jl.credit-jl.debit),0)
      into v_vendor_balance
    from erp.journal_lines jl
    join erp.journal_entries je on je.id=jl.journal_entry_id
    where je.status in ('POSTED','REVERSED')
      and jl.account_id=v_ap_vendor_account
      and jl.vendor_id=v_vendor_id;

    select coalesce(sum(
      coalesce((x->>'credit')::numeric,0)-coalesce((x->>'debit')::numeric,0)
    ),0)
      into v_vendor_delta
    from jsonb_array_elements(p_lines) x
    where nullif(x->>'vendor_id','')::uuid=v_vendor_id
      and (
        (x ? 'mapping_key' and x->>'mapping_key'='AP_VENDOR')
        or (x ? 'account_id' and nullif(x->>'account_id','')::uuid=v_ap_vendor_account)
      );

    if v_vendor_balance::text in('NaN','Infinity','-Infinity') or v_vendor_balance+v_vendor_delta < 0 then
      raise exception 'Transaksi ini membuat hutang vendor menjadi negatif. Hutang saat ini %, perubahan %, hasil %. Reverse/koreksi pembayaran, claim, atau invoice terkait dulu; kelebihan bayar/claim vendor harus masuk workflow piutang vendor terpisah.',
        round(v_vendor_balance,2),round(v_vendor_delta,2),round(v_vendor_balance+v_vendor_delta,2);
    end if;
  end loop;

  v_gl_date:=erp.resolve_accounting_transaction_date(p_transaction_date);
  v_number:='JRN-'||to_char((clock_timestamp() AT TIME ZONE 'Asia/Jakarta'),'YYYYMMDDHH24MISSMS')||'-'||substr(gen_random_uuid()::text,1,8);
  insert into erp.journal_entries(journal_number,economic_date,transaction_date,posting_at,source_type,source_id,description,status,created_by)
  values(v_number,p_transaction_date,v_gl_date,statement_timestamp(),p_source_type,p_source_id,p_description,'POSTED',erp.current_app_user_id()) returning id into v_entry_id;

  for r in select * from jsonb_array_elements(p_lines) loop
    if r?'account_id' then v_account_id:=(r->>'account_id')::uuid; else v_account_id:=erp.account_id(r->>'mapping_key'); end if;
    insert into erp.journal_lines(journal_entry_id,account_id,description,debit,credit,customer_id,vendor_id,contractor_id,po_id,product_id)
    values(v_entry_id,v_account_id,r->>'description',coalesce((r->>'debit')::numeric,0),coalesce((r->>'credit')::numeric,0),nullif(r->>'customer_id','')::uuid,nullif(r->>'vendor_id','')::uuid,nullif(r->>'contractor_id','')::uuid,nullif(r->>'po_id','')::uuid,nullif(r->>'product_id','')::uuid);
  end loop;

  insert into erp.account_daily_balances(balance_date,account_id,debit_total,credit_total)
  select v_gl_date,jl.account_id,sum(jl.debit),sum(jl.credit) from erp.journal_lines jl where jl.journal_entry_id=v_entry_id group by jl.account_id
  on conflict(balance_date,account_id) do update set debit_total=erp.account_daily_balances.debit_total+excluded.debit_total,credit_total=erp.account_daily_balances.credit_total+excluded.credit_total,updated_at=statement_timestamp();

  if v_gl_date<>p_transaction_date then
    insert into erp.audit_logs(entity_type,entity_id,action,new_data,changed_by,change_reason)
    values('journal_entries',v_entry_id,'POST',jsonb_build_object('economic_date',p_transaction_date,'transaction_date',v_gl_date,'period_shifted',true,'source_type',p_source_type,'source_id',p_source_id),erp.current_app_user_id(),'Late/backdated posting moved to open accounting period');
  end if;
  return v_entry_id;
end;
$function$

erp.post_payroll_payment(uuid).definition:
CREATE OR REPLACE FUNCTION erp.post_payroll_payment(p_payroll_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  p erp.payroll_settlements%rowtype;
  v_cash uuid;
  v_material_deduction numeric(20,2):=0;
  v_other_deduction numeric(20,2):=0;v_cash_advance numeric(20,2):=0;
  v_expected_attendance numeric(20,2):=0;
  v_actual_attendance numeric(20,2):=0;
  v_attendance_journal_count bigint:=0;
  r record;
begin
  perform erp.require_internal();
  select * into p from erp.payroll_settlements where id=p_payroll_id for update;
  if p.id is null or p.status<>'APPROVED' then raise exception 'Payroll must be APPROVED'; end if;
  perform erp.check_opening_cash_advance_payroll_v1(p.id);
  perform erp.bb_check_opening_payable_payroll_v1(p.id);
  perform erp._cp3_lock_business_period(p.period_start,p.period_end);
  if p.net_payable<0 then raise exception 'Payroll net payable cannot be negative; carry deductions forward instead'; end if;
  if p.payment_date is null then raise exception 'Payroll payment date is required'; end if;
  if p.payment_date>((statement_timestamp() AT TIME ZONE 'Asia/Jakarta'::text))::date then raise exception 'Tanggal pembayaran payroll berada di masa depan'; end if;
  if p.net_payable>0 then
    select coa_account_id into v_cash from erp.cash_accounts where id=p.payment_cash_account_id and is_active=true;
    if v_cash is null then raise exception 'Active payroll cash/bank account is required when cash payment is positive'; end if;
  end if;

  v_expected_attendance:=round(coalesce(p.attendance_total,0),2);
  select count(distinct je.id),coalesce(sum(jl.debit),0)
    into v_attendance_journal_count,v_actual_attendance
  from erp.journal_entries je
  join erp.journal_lines jl on jl.journal_entry_id=je.id
  where je.source_type='PAYROLL_ATTENDANCE_ACCRUAL' and je.source_id=p.id and je.status='POSTED'
    and jl.account_id=erp.account_id('WIP') and jl.debit>0;
  if (v_expected_attendance=0 and v_attendance_journal_count<>0)
     or (v_expected_attendance>0 and (v_attendance_journal_count<>1 or round(v_actual_attendance,2) is distinct from v_expected_attendance)) then
    raise exception 'PAYROLL_APPROVAL_ACCRUAL_MISSING_OR_MISMATCH: expected attendance %, journal count %, WIP debit %',
      v_expected_attendance,v_attendance_journal_count,round(v_actual_attendance,2);
  end if;

  select coalesce(sum(amount),0) into v_material_deduction
  from erp.payroll_deductions where payroll_id=p.id and deduction_type='MATERIAL_KASBON';
  select coalesce(sum(amount),0) into v_other_deduction
  from erp.payroll_deductions where payroll_id=p.id and deduction_type not in('MATERIAL_KASBON','CASH_ADVANCE');
  if v_material_deduction>0 then
    perform erp.post_journal('PAYROLL_MATERIAL_DEDUCTION',p.id,p.payment_date,
      'Physical material/accessory purchase deduction',jsonb_build_array(
        jsonb_build_object('mapping_key','CONTRACTOR_PAYABLE','debit',v_material_deduction,'credit',0,'contractor_id',p.contractor_id),
        jsonb_build_object('mapping_key','CONTRACTOR_RECEIVABLE','debit',0,'credit',v_material_deduction,'contractor_id',p.contractor_id)));
  end if;
  select coalesce(sum(amount),0) into v_cash_advance from erp.payroll_deductions
    where payroll_id=p.id and deduction_type='CASH_ADVANCE';
  if v_cash_advance>0 then
    perform erp.post_journal('PAYROLL_CASH_ADVANCE_DEDUCTION',p.id,p.payment_date,'Pelunasan kasbon tunai melalui payroll',jsonb_build_array(
      jsonb_build_object('mapping_key','CONTRACTOR_PAYABLE','debit',v_cash_advance,'credit',0,'contractor_id',p.contractor_id),
      jsonb_build_object('mapping_key','CONTRACTOR_RECEIVABLE','debit',0,'credit',v_cash_advance,'contractor_id',p.contractor_id)));
  end if;
  if v_other_deduction>0 then
    perform erp.post_journal('PAYROLL_OTHER_DEDUCTION',p.id,p.payment_date,
      'BS/penalty/other payroll deduction',jsonb_build_array(
        jsonb_build_object('mapping_key','CONTRACTOR_PAYABLE','debit',v_other_deduction,'credit',0,'contractor_id',p.contractor_id),
        jsonb_build_object('mapping_key','OTHER_INCOME','debit',0,'credit',v_other_deduction,'contractor_id',p.contractor_id)));
  end if;
  if p.net_payable>0 then
    perform erp.post_journal('PAYROLL_PAYMENT',p.id,p.payment_date,'Mandor payroll payment',jsonb_build_array(
      jsonb_build_object('mapping_key','CONTRACTOR_PAYABLE','debit',p.net_payable,'credit',0,'contractor_id',p.contractor_id),
      jsonb_build_object('account_id',v_cash,'debit',0,'credit',p.net_payable,'contractor_id',p.contractor_id)));
  end if;

  update erp.payroll_settlements set status='PAID',settled_at=statement_timestamp(),updated_at=statement_timestamp() where id=p.id;
  update erp.opening_subledger_balances b set settled_amount=b.settled_amount+x.amount,
    status=case when b.settled_amount+x.amount=b.original_amount then 'SETTLED' else 'PARTIAL' end,updated_at=statement_timestamp()
  from(select opening_cash_advance_balance_id id,sum(amount) amount from erp.payroll_deductions
    where payroll_id=p.id and deduction_type='CASH_ADVANCE' group by opening_cash_advance_balance_id) x where b.id=x.id;
  -- BB (ALL-Y01): imported contractor payables paid by this payroll, then the dated floor of every opening balance it touched.
  update erp.opening_subledger_balances b set settled_amount=b.settled_amount+x.amount,
    status=case when b.settled_amount+x.amount=b.original_amount then 'SETTLED' else 'PARTIAL' end,updated_at=statement_timestamp()
  from(select opening_payable_balance_id id,sum(amount) amount from erp.payroll_reimbursements
    where payroll_id=p.id and source_type='OPENING_PAYABLE' group by opening_payable_balance_id) x where b.id=x.id;
  for r in select z.id from(select opening_payable_balance_id id from erp.payroll_reimbursements where payroll_id=p.id and opening_payable_balance_id is not null
      union select opening_cash_advance_balance_id from erp.payroll_deductions where payroll_id=p.id and opening_cash_advance_balance_id is not null) z order by z.id
  loop perform erp.bb_assert_opening_balance_floor_v1(r.id,p.payment_date); end loop;

  for r in select distinct pd.contractor_issue_item_id id from erp.payroll_deductions pd
           where pd.payroll_id=p.id and pd.contractor_issue_item_id is not null
  loop perform erp.refresh_contractor_issue_payroll_status(r.id); end loop;
  update erp.contractor_accessory_reimbursement_entitlements e set payroll_status='SETTLED'
  where e.id in(select pr.source_id from erp.payroll_reimbursements pr
                where pr.payroll_id=p.id and pr.source_type='ACCESSORY_BOM' and pr.source_id is not null);
  for r in
    select distinct bc.id as bs_case_id from erp.bs_cases bc
    where exists(select 1 from erp.payroll_work_items pwi where pwi.payroll_id=p.id and pwi.po_id=bc.po_id)
       or exists(select 1 from erp.payroll_work_items pwi join erp.rework_component_lines rcl on rcl.id=pwi.source_id
                 join erp.bs_case_components bcc on bcc.id=rcl.bs_case_component_id
                 where pwi.payroll_id=p.id and bcc.bs_case_id=bc.id)
  loop perform erp.rebuild_bs_component_counters(r.bs_case_id); end loop;

  insert into erp.audit_logs(entity_type,entity_id,action,new_data,changed_by,change_reason)
  values('payroll_settlements',p.id,'POST',
    jsonb_build_object('lifecycle_action','PAY','payment_settlement_only',true,'attendance_accrual_created_at_payment',false),
    erp.current_app_user_id(),'Payroll payment settled approved payable without recognizing attendance cost again');
end;
$function$

erp.bump_row_version().definition:
CREATE OR REPLACE FUNCTION erp.bump_row_version()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
begin
  new.row_version := old.row_version + 1;
